{
  "name": "mac_rx_parse_phy_header",
  "confidence": "medium",
  "docstring": "Parses a received PHY/frame header, validates per-channel context state, updates stored signal/mode fields under lock, and issues corresponding HCI/SDIO host notifications.",
  "subsystem": "mac",
  "var_renames": {
    "a2": "frame_hdr",
    "a3": "rx_handle",
    "v3": "header_type",
    "v7": "chan_idx",
    "v9": "phy_word",
    "v10": "chan_contexts",
    "v11": "chan_ctx",
    "v12": "chan_ctx_offset",
    "v18": "chan_ctx",
    "v19": "ctx_byte_16",
    "v20": "ctx_byte_22",
    "v21": "timer_value",
    "v27": "sdio_byte",
    "v28": "sdio_index",
    "v29": "global_mode_state",
    "v30": "chan_ctx",
    "a4a": "chan_ctx"
  },
  "struct_hints": [
    {
      "offset": 7,
      "meaning": "received-buffer byte passed to the SDIO command helper"
    },
    {
      "offset": 13,
      "meaning": "received-frame header type/version discriminator byte"
    },
    {
      "offset": 14,
      "meaning": "header byte compared against per-channel context byte 23"
    },
    {
      "offset": 15,
      "meaning": "16-bit header field that must be zero for a valid context match"
    },
    {
      "offset": 17,
      "meaning": "16-bit PHY word; bits 2..5 provide an expected nibble for context byte 22, and bits 6+ provide a signal/quality metric"
    },
    {
      "offset": 16,
      "meaning": "per-channel context byte used to select an SDIO register-table entry"
    },
    {
      "offset": 20,
      "meaning": "per-channel stored minimum/last PHY signal or quality metric"
    },
    {
      "offset": 22,
      "meaning": "per-channel expected low nibble derived from header PHY word"
    },
    {
      "offset": 23,
      "meaning": "per-channel expected byte matching header buffer offset 14"
    },
    {
      "offset": 24,
      "meaning": "per-channel PHY mode/state byte updated from header or global mode state"
    }
  ]
}
